using System.Text.Json;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evals.Tests;

[TestClass]
public class QualityEvalTests
{
    private static readonly string GoldenPath =
        Path.Combine(AppContext.BaseDirectory, "Quality", "golden.json");

    private static readonly string RubricPath =
        Path.Combine(AppContext.BaseDirectory, "Quality", "rubric.md");

    private static IList<GoldenEntry>? s_goldenEntries;
    private static string? s_rubric;

    [ClassInitialize]
    public static void Initialize(TestContext _)
    {
        var json = File.ReadAllText(GoldenPath);
        s_goldenEntries = JsonSerializer.Deserialize<List<GoldenEntry>>(json,
            new JsonSerializerOptions { PropertyNameCaseInsensitive = true })!;

        s_rubric = File.ReadAllText(RubricPath);
    }

    [TestMethod]
    public void GoldenFileIsLoaded()
    {
        Assert.IsNotNull(s_goldenEntries);
        Assert.IsTrue(s_goldenEntries.Count > 0, "golden.json must contain at least one entry.");
    }

    [TestMethod]
    public void RubricIsLoaded()
    {
        Assert.IsNotNull(s_rubric);
        Assert.IsFalse(string.IsNullOrWhiteSpace(s_rubric), "rubric.md must not be empty.");
    }

    [TestMethod]
    public void AllEntriesHaveExpectedTraits()
    {
        Assert.IsNotNull(s_goldenEntries);
        foreach (var entry in s_goldenEntries)
        {
            Assert.IsFalse(
                string.IsNullOrWhiteSpace(entry.UserMessage),
                $"Entry '{entry.Id}' must have a user_message.");
            Assert.IsTrue(
                entry.ExpectedTraits?.Count > 0,
                $"Entry '{entry.Id}' must define at least one expected trait.");
        }
    }

    internal sealed class GoldenEntry
    {
        public string Id { get; set; } = string.Empty;
        public string UserMessage { get; set; } = string.Empty;
        public List<string> ExpectedTraits { get; set; } = new();
    }
}

